update public.site_texts set value = 'Osvaldo Santos is a clinical and health psychologist with experience in clinical practice, research, and teaching. He is a faculty member at the Lisbon School of Medicine, University of Lisbon, and coordinator of the Environmental Health Behavior Laboratory (EnviHeB Lab), at the Institute of Environmental Health of the Lisbon School of Medicine.', updated_at = now() where key = 'team.osvaldo.bio' and lang = 'en';
update public.site_texts set value = 'Osvaldo Santos é um psicólogo clínico e da saúde com experiência em prática clínica, investigação e ensino. É docente da Faculdade de Medicina da Universidade de Lisboa, sendo o coordenador do Laboratório de Comportamento de Saúde Ambiental (EnviHeB Lab), do Instituto de Saúde Ambiental da Faculdade de Medicina de Lisboa.', updated_at = now() where key = 'team.osvaldo.bio' and lang = 'pt';
delete from public.site_texts where key = 'team.osvaldo.achievements.cited';